import hashlib,importlib.util,json,os,pathlib,shutil,sys,time,unittest
ROOT=pathlib.Path(sys.argv[1]); E=pathlib.Path(sys.argv[2])
spec=importlib.util.spec_from_file_location("hepta_canary_original",ROOT/"tests/test_native_canary_resume.py")
mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
def save(p,v): p.write_text(json.dumps(v,indent=2)+"\n")
def states(path):
 r={"fixture_path":str(path)}
 for n in ("calls.jsonl","continuation.json","report.json"):
  p=path/n;r[n]={"exists":p.exists()}
  if p.exists():
   b=p.read_bytes();r[n].update(bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
   try:r[n]["value"]=[json.loads(x) for x in b.splitlines()] if n.endswith("jsonl") else json.loads(b)
   except Exception as ex:r[n]["parse_error"]=repr(ex)
 return r
class ObservedCanary(mod.CanaryResume):
 def setUp(self):
  super().setUp();self.observed_calls=[];self.addCleanup(self.capture_original_cleanup)
 def capture_original_cleanup(self):
  save(E/"final-fixture-state.json",states(self.root))
  shutil.copytree(self.root,E/"fixture-copy",symlinks=False)
  save(E/"observed-helper-calls.json",self.observed_calls)
 def run_helper(self,*args,**kwargs):
  n=len(self.observed_calls)+1;started=time.monotonic()
  row={"invocation":n,"started_unix_ns":time.time_ns(),"args":args,"kwargs":kwargs,"default_total_timeout_seconds":10,"default_driver_call_timeout_seconds":2}
  try:
   value=super().run_helper(*args,**kwargs)
   row.update(returncode=value.returncode,stdout=value.stdout,stderr=value.stderr);return value
  except BaseException as error:
   row.update(error_type=type(error).__name__,error=str(error));raise
  finally:
   row["elapsed_seconds"]=time.monotonic()-started;row["after"]=states(self.root)
   self.observed_calls.append(row);save(E/("helper-invocation-%02d.json"%n),row)
suite=unittest.TestSuite([ObservedCanary("test_existing_receipt_never_gets_replaced_or_repeated")])
result=unittest.TextTestRunner(verbosity=2).run(suite)
save(E/"unittest-result.json",{"successful":result.wasSuccessful(),"tests_run":result.testsRun,"errors":[[str(t),trace] for t,trace in result.errors],"failures":[[str(t),trace] for t,trace in result.failures],"skipped":result.skipped})
raise SystemExit(0 if result.wasSuccessful() else 1)
